"""Load screening and installed-mass comparison, not a qualified landing simulation."""
from pathlib import Path
import json,math,hashlib
H=Path(__file__).resolve().parent;O=H/'Ausgabe';R=H.parent
P=json.loads((H/'parameter.json').read_text());M=json.loads((O/'Regler_Montage.json').read_text());old=json.loads((R/'quad_r380_d11/Ausgabe/Regler_Montage.json').read_text())['configurations'];modules=json.loads((O/'Reglerhalter_Instanzen.json').read_text())
A=math.pi/4*(P['leg_od_mm']**2-P['leg_id_mm']**2);I=math.pi/64*(P['leg_od_mm']**4-P['leg_id_mm']**4);mass=P['design_total_mass_kg'];g=9.81;E=P['leg_axial_modulus_assumption_MPa'];rows=[]
for c in M['configurations']:
 m=next(m for m in modules if m['propeller_index']==c['propeller_index'] and m['variant']==c['variant']);prev=next(x for x in old if x['propeller_index']==c['propeller_index'] and x['variant']==c['variant']);L=max(x['length_mm'] for x in c['legs']);cut=[dict(length_mm=round(x['length_mm'],3),quantity=4,article='CBU 2017 1005 TG nominal20/17',ID_tolerance_verified=False) for x in c['legs']];carbon=sum(p['mass_kg'] for p in m['parts'] if p['role']=='landing_CFK');loadcases=[]
 for factor,feet in [(1,4),(3,4),(3,2),(3,1)]:
  F=mass*g*factor/feet;f=F/2;od=35 if c['variant']=='V1' else 20;B=P['bond_length_mm']-P['end_isolation_mm'];bond_area=math.pi*(P['leg_id_mm']-2*P['bond_radial_gap_mm'])*B
  loadcases.append(dict(peak_load_factor=factor,contacting_feet=feet,vertical_force_per_foot_N=F,force_each_leg_equal_sharing_N=f,CFK_axial_stress_equal_sharing_MPa=f/A,CFK_stress_if_one_column_takes_entire_foot_MPa=F/A,Euler_pinned_column_N=math.pi**2*E*I/L**2,elastic_column_shortening_equal_mm=f*L/(E*A),bond_mean_shear_equal_MPa=f/bond_area,bond_mean_shear_one_column_MPa=F/bond_area,arm_projected_bearing_mean_MPa=F/(2*P['clamp_grip_mm']*od),qualified=False))
 rows.append(dict(propeller_index=c['propeller_index'],variant=c['variant'],module_mass_kg=c['carrier_mass_each_kg'],four_module_mass_kg=4*c['carrier_mass_each_kg'],delta_vs_D11_four_module_kg=4*(c['carrier_mass_each_kg']-prev['carrier_mass_each_kg']),mass_saved_vs_same_geometry_Al_columns_kg=4*carbon*(2700/1600-1),CFK_cut_list=cut,loadcases=loadcases))
energy=[]
for speed in [.2,.3,.5,.75,1.0]:energy.append(dict(sink_speed_m_s=speed,kinetic_energy_J=.5*mass*speed**2,ideal_constant_deceleration_stroke_for_3g_mm=1000*speed**2/(2*g*(3-1)),equivalent_load_factor_at_2mm_stroke=1+speed**2/(2*g*.002)))
result=dict(native_sha256=M['native_sha256'],production_ready=False,scope='Ideal axial column, Euler pinned-column and mean bond/bearing screens only.160kg assumed all-up mass includes100kg payload;no measured vehicle mass or landing dynamics.Finite-element/whole-frame arm bending,torsion,unequal ground contact,stress concentrations,preload,CFK crushing,adhesive peel/fatigue,temperature,impact validation and material allowables are missing.',modulus_assumption_MPa=E,leg_area_mm2=A,leg_second_moment_mm4=I,configurations=rows,landing_energy_scenarios=energy,sole_damping_credit=False,warning='An8mm wear sole is not a qualified shock absorber.3g peak load is an assumed screen,not proof that the sole can absorb a landing event.2mm stroke is an illustration,not an allowable compression.')
(O/'Landelast_Screening.json').write_text(json.dumps(result,indent=2));print('50 load/mass screens written;qualification remains false')
# Human-readable default case and complete parameter-dependent cut list are retained with the JSON.
c=next(x for x in rows if x['propeller_index']==9 and x['variant']=='V4');f=c['loadcases'][2]
(O/'Landelast_Kurzbericht.md').write_text(f'''# Vorbemessung, keine Freigabe\n\nDefault V4/42 Zoll: vier kombinierte Einheiten {c['four_module_mass_kg']:.3f} kg, Zuwachs gegenüber D11 {c['delta_vs_D11_four_module_kg']:.3f} kg. Gleichgeometrische Aluminiumstützen wären {c['mass_saved_vs_same_geometry_Al_columns_kg']*1000:.0f} g schwerer. Tatsächliche Regler fehlen in beiden Massen.\n\nAnnahme: 160 kg Gesamtmasse einschließlich 100 kg Nutzlast, 3 g vertikaler Spitzenlastfaktor auf zwei Füßen. Daraus folgen {f['vertical_force_per_foot_N']:.0f} N je Fuß, bei gleicher Teilung {f['force_each_leg_equal_sharing_N']:.0f} N pro CFK-Stütze. Mittlere axiale Spannung {f['CFK_axial_stress_equal_sharing_MPa']:.1f} MPa, mittlere Klebfugenschubspannung {f['bond_mean_shear_equal_MPa']:.2f} MPa. Es liegen keine qualifizierten Vergleichszulässigkeiten vor; diese Zahlen begründen keine Tragfähigkeitsfreigabe.\n\nBei 0,5 m/s Sinkgeschwindigkeit müssen bei 160 kg bereits 20 J Bewegungsenergie abgebaut werden. Für ideal konstante Verzögerung bei insgesamt 3 g wären 6,37 mm Weg erforderlich; bei nur 2 mm wären es etwa 7,37 g. Reale Spitzen können höher liegen. Die Sohle und der Rahmen haben keine gemessene Kraft-Weg-Kennlinie.\n\nDie vergrößerten Schellen verteilen die nominelle Kontaktlast; Rohrquetschung, Verbundlaminat, Spannkraft und Gesamtarm bleiben nachzuweisen. Isolierte Stützenrechnung ersetzt keinen Nachweis der Carbonarme und ihrer Rahmen-/Motoranschlüsse.\n\nZuschnitt (je Länge vier Stück, Ø20/17): {c['CFK_cut_list'][0]['length_mm']:.2f} mm und {c['CFK_cut_list'][1]['length_mm']:.2f} mm. Sägeschnitt/Endbearbeitung und Bauteiltoleranzen müssen vor Fertigung ergänzt werden.\n''')
